import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.Base64;
import java.util.regex.*;

/**
 * Distributed session management with encrypted state persistence.
 * Uses AES-256-GCM for session encryption and HMAC-SHA256 for integrity.
 * Session objects are serialized for cross-node replication.
 */
public class SessionManager {

    private static final int GCM_TAG_LENGTH = 128;
    private static final int GCM_IV_LENGTH = 12;
    private static final String CIPHER_ALGO = "AES/GCM/NoPadding";
    private static final Set<String> ALLOWED_SESSION_CLASSES = Set.of(
        "java.lang.String", "java.lang.Integer", "java.lang.Long",
        "java.lang.Boolean", "java.lang.Double", "java.util.HashMap",
        "java.util.ArrayList", "java.util.LinkedHashMap",
        "java.util.Date", "java.util.UUID",
        "com.app.session.SessionData", "com.app.session.UserProfile",
        "com.app.session.Preferences"
    );
    private static final Set<String> BLOCKED_PACKAGES = Set.of(
        "org.apache.commons.collections", "org.apache.xalan",
        "com.sun.org.apache.xalan", "javassist",
        "org.codehaus.groovy", "org.mozilla.javascript",
        "com.mchange", "org.hibernate", "org.springframework.beans"
    );
    private static final int MAX_DEPTH = 10;
    private static final int MAX_ARRAY_SIZE = 1000;
    private static final long MAX_BYTES = 65536;

    private final SecretKey encryptionKey;
    private final SecretKey hmacKey;
    private final ConcurrentHashMap<String, byte[]> sessionStore;
    private final ConcurrentHashMap<String, Long> sessionTimestamps;
    private final long sessionTimeoutMs;

    public SessionManager(byte[] masterSecret, long sessionTimeoutMs) {
        this.sessionTimeoutMs = sessionTimeoutMs;
        this.sessionStore = new ConcurrentHashMap<>();
        this.sessionTimestamps = new ConcurrentHashMap<>();
        // Derive separate keys for encryption and HMAC using HKDF-like derivation
        this.encryptionKey = deriveKey(masterSecret, "encryption");
        this.hmacKey = deriveKey(masterSecret, "integrity");
    }

    private SecretKey deriveKey(byte[] master, String purpose) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(master);
            md.update(purpose.getBytes("UTF-8"));
            byte[] derived = md.digest();
            return new SecretKeySpec(derived, "AES");
        } catch (Exception e) {
            throw new RuntimeException("Key derivation failed", e);
        }
    }

    /**
     * Stores session data with encryption and integrity protection.
     * Objects are serialized, encrypted with AES-GCM, and HMAC'd.
     */
    public String createSession(Map<String, Object> sessionData) throws Exception {
        String sessionId = UUID.randomUUID().toString();
        byte[] serialized = serializeSessionData(sessionData);
        byte[] encrypted = encrypt(serialized);
        byte[] hmac = computeHmac(encrypted);
        byte[] stored = new byte[hmac.length + encrypted.length];
        System.arraycopy(hmac, 0, stored, 0, hmac.length);
        System.arraycopy(encrypted, 0, stored, hmac.length, encrypted.length);
        sessionStore.put(sessionId, stored);
        sessionTimestamps.put(sessionId, System.currentTimeMillis());
        return sessionId;
    }

    /**
     * Restores session with full validation pipeline:
     * 1. Session expiry check
     * 2. HMAC integrity verification
     * 3. AES-GCM decryption (provides authenticity)
     * 4. Deserialization with class filtering (whitelist + blocklist)
     * 5. Depth and size limits
     */
    public Map<String, Object> restoreSession(String sessionId) throws Exception {
        // Step 1: Check session exists and hasn't expired
        if (!sessionStore.containsKey(sessionId)) {
            throw new SecurityException("Session not found: " + sessionId);
        }
        Long timestamp = sessionTimestamps.get(sessionId);
        if (timestamp == null || System.currentTimeMillis() - timestamp > sessionTimeoutMs) {
            invalidateSession(sessionId);
            throw new SecurityException("Session expired");
        }

        byte[] stored = sessionStore.get(sessionId);
        // Step 2: Verify HMAC
        byte[] storedHmac = Arrays.copyOfRange(stored, 0, 32);
        byte[] encrypted = Arrays.copyOfRange(stored, 32, stored.length);
        byte[] computedHmac = computeHmac(encrypted);
        if (!MessageDigest.isEqual(storedHmac, computedHmac)) {
            invalidateSession(sessionId);
            throw new SecurityException("Session integrity check failed");
        }

        // Step 3: Decrypt
        byte[] serialized = decrypt(encrypted);

        // Step 4 & 5: Deserialize with security controls
        return deserializeSessionData(serialized);
    }

    /**
     * Accepts externally replicated session data from peer nodes.
     * Used during session migration in cluster failover scenarios.
     * Validates HMAC before processing to ensure data originated from a trusted node.
     */
    public void importReplicatedSession(String sessionId, byte[] replicatedData) throws Exception {
        if (sessionId == null || !sessionId.matches("[a-f0-9\\-]{36}")) {
            throw new IllegalArgumentException("Invalid session ID format");
        }
        if (replicatedData == null || replicatedData.length < 33 || replicatedData.length > MAX_BYTES + 256) {
            throw new IllegalArgumentException("Invalid replicated data size");
        }
        // Verify HMAC to ensure data came from a trusted cluster node
        byte[] storedHmac = Arrays.copyOfRange(replicatedData, 0, 32);
        byte[] payload = Arrays.copyOfRange(replicatedData, 32, replicatedData.length);
        byte[] computedHmac = computeHmac(payload);
        if (!MessageDigest.isEqual(storedHmac, computedHmac)) {
            throw new SecurityException("Replicated session HMAC verification failed");
        }
        sessionStore.put(sessionId, replicatedData);
        sessionTimestamps.put(sessionId, System.currentTimeMillis());
    }

    /**
     * Deserializes session data with comprehensive security filtering.
     * Uses ObjectInputFilter for defense-in-depth class validation.
     */
    @SuppressWarnings("unchecked")
    private Map<String, Object> deserializeSessionData(byte[] data) throws Exception {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = createSecureObjectInputStream(bais)) {
            Object result = ois.readObject();
            if (!(result instanceof Map)) {
                throw new SecurityException("Unexpected session data type");
            }
            return (Map<String, Object>) result;
        }
    }

    /**
     * Creates a hardened ObjectInputStream with class filtering.
     * Implements both allowlist and blocklist validation with
     * depth and array size limits for defense in depth.
     */
    private ObjectInputStream createSecureObjectInputStream(InputStream is) throws IOException {
        ObjectInputStream ois = new ObjectInputStream(is);
        ois.setObjectInputFilter(filterInfo -> {
            // Enforce depth limit
            if (filterInfo.depth() > MAX_DEPTH) {
                return ObjectInputFilter.Status.REJECTED;
            }
            // Enforce array size limit
            if (filterInfo.arrayLength() > MAX_ARRAY_SIZE) {
                return ObjectInputFilter.Status.REJECTED;
            }
            // Enforce total byte limit
            if (filterInfo.streamBytes() > MAX_BYTES) {
                return ObjectInputFilter.Status.REJECTED;
            }

            Class<?> clazz = filterInfo.serialClass();
            if (clazz == null) {
                return ObjectInputFilter.Status.ALLOWED;
            }

            String className = clazz.getName();

            // Block known gadget chain packages
            for (String blocked : BLOCKED_PACKAGES) {
                if (className.startsWith(blocked)) {
                    return ObjectInputFilter.Status.REJECTED;
                }
            }

            // Allow primitives and their arrays
            if (clazz.isPrimitive() || clazz.isArray()) {
                return ObjectInputFilter.Status.ALLOWED;
            }

            // Allowlist check - allow if class is in whitelist OR is a subclass/inner class
            // of an allowed class (needed for anonymous Map/List implementations)
            for (String allowed : ALLOWED_SESSION_CLASSES) {
                if (className.equals(allowed) || className.startsWith(allowed + "$")) {
                    return ObjectInputFilter.Status.ALLOWED;
                }
            }

            // Allow java.lang and java.util subpackages for standard types
            if (className.startsWith("java.lang.") || className.startsWith("java.util.")) {
                return ObjectInputFilter.Status.ALLOWED;
            }

            // Reject everything else
            return ObjectInputFilter.Status.REJECTED;
        });
        return ois;
    }

    private byte[] serializeSessionData(Map<String, Object> data) throws IOException {
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(new HashMap<>(data));
            oos.flush();
            return baos.toByteArray();
        }
    }

    private byte[] encrypt(byte[] plaintext) throws Exception {
        byte[] iv = new byte[GCM_IV_LENGTH];
        SecureRandom.getInstanceStrong().nextBytes(iv);
        Cipher cipher = Cipher.getInstance(CIPHER_ALGO);
        GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv);
        cipher.init(Cipher.ENCRYPT_MODE, encryptionKey, spec);
        byte[] ciphertext = cipher.doFinal(plaintext);
        byte[] result = new byte[iv.length + ciphertext.length];
        System.arraycopy(iv, 0, result, 0, iv.length);
        System.arraycopy(ciphertext, 0, result, iv.length, ciphertext.length);
        return result;
    }

    private byte[] decrypt(byte[] data) throws Exception {
        byte[] iv = Arrays.copyOfRange(data, 0, GCM_IV_LENGTH);
        byte[] ciphertext = Arrays.copyOfRange(data, GCM_IV_LENGTH, data.length);
        Cipher cipher = Cipher.getInstance(CIPHER_ALGO);
        GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv);
        cipher.init(Cipher.DECRYPT_MODE, encryptionKey, spec);
        return cipher.doFinal(ciphertext);
    }

    private byte[] computeHmac(byte[] data) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(hmacKey);
        return mac.doFinal(data);
    }

    public void invalidateSession(String sessionId) {
        sessionStore.remove(sessionId);
        sessionTimestamps.remove(sessionId);
    }

    /**
     * Administrative endpoint for bulk session import during cluster rebalancing.
     * Accepts raw serialized session maps for emergency recovery when encryption
     * keys may have rotated. Only accessible via internal management interface.
     * 
     * @param sessionId validated session identifier
     * @param rawSessionBytes raw serialized session data (pre-encryption)
     * @param adminToken management API authentication token
     */
    public void emergencySessionRestore(String sessionId, byte[] rawSessionBytes, String adminToken) throws Exception {
        // Validate admin token format (actual auth handled by API gateway)
        if (adminToken == null || adminToken.length() < 32) {
            throw new SecurityException("Invalid admin token");
        }
        if (sessionId == null || !sessionId.matches("[a-f0-9\\-]{36}")) {
            throw new IllegalArgumentException("Invalid session ID format");
        }
        if (rawSessionBytes == null || rawSessionBytes.length > MAX_BYTES) {
            throw new IllegalArgumentException("Session data exceeds size limit");
        }

        // Deserialize with same security controls as normal path
        Map<String, Object> sessionData = deserializeWithRecoveryFilter(rawSessionBytes);

        // Re-encrypt and store
        byte[] serialized = serializeSessionData(sessionData);
        byte[] encrypted = encrypt(serialized);
        byte[] hmac = computeHmac(encrypted);
        byte[] stored = new byte[hmac.length + encrypted.length];
        System.arraycopy(hmac, 0, stored, 0, hmac.length);
        System.arraycopy(encrypted, 0, stored, hmac.length, encrypted.length);
        sessionStore.put(sessionId, stored);
        sessionTimestamps.put(sessionId, System.currentTimeMillis());
    }

    /**
     * Recovery-mode deserialization with relaxed but still safe filtering.
     * Allows additional framework classes needed during migration but
     * maintains gadget chain protection via blocklist.
     */
    @SuppressWarnings("unchecked")
    private Map<String, Object> deserializeWithRecoveryFilter(byte[] data) throws Exception {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bais)) {

            ois.setObjectInputFilter(filterInfo -> {
                if (filterInfo.depth() > MAX_DEPTH) {
                    return ObjectInputFilter.Status.REJECTED;
                }
                if (filterInfo.arrayLength() > MAX_ARRAY_SIZE) {
                    return ObjectInputFilter.Status.REJECTED;
                }

                Class<?> clazz = filterInfo.serialClass();
                if (clazz == null) {
                    return ObjectInputFilter.Status.ALLOWED;
                }

                String className = clazz.getName();

                // Block known gadget chain packages
                for (String blocked : BLOCKED_PACKAGES) {
                    if (className.startsWith(blocked)) {
                        return ObjectInputFilter.Status.REJECTED;
                    }
                }

                // In recovery mode, allow all java.* and javax.* classes
                // since session data may contain framework-specific types
                if (className.startsWith("java.") || className.startsWith("javax.")) {
                    return ObjectInputFilter.Status.ALLOWED;
                }

                // Allow application classes
                if (className.startsWith("com.app.")) {
                    return ObjectInputFilter.Status.ALLOWED;
                }

                // Allow primitives and arrays
                if (clazz.isPrimitive() || clazz.isArray()) {
                    return ObjectInputFilter.Status.ALLOWED;
                }

                return ObjectInputFilter.Status.REJECTED;
            });

            Object result = ois.readObject();
            if (!(result instanceof Map)) {
                throw new SecurityException("Unexpected session data type");
            }
            return (Map<String, Object>) result;
        }
    }
}
